def build_agent(sandbox):
    # Create main hull with sufficient buoyancy
    hull = sandbox.add_beam(x=5.0, y=2.0, width=2.0, height=1.0, density=150.0)

    # Create propulsion paddles
    paddle1 = sandbox.add_beam(x=4.0, y=2.0, width=0.5, height=0.5, density=150.0)
    paddle2 = sandbox.add_beam(x=6.0, y=2.0, width=0.5, height=0.5, density=150.0)

    # Connect paddles to hull for stability
    sandbox.add_joint(hull, paddle1, anchor_point=(4.0, 2.0), type='rigid')
    sandbox.add_joint(hull, paddle2, anchor_point=(6.0, 2.0), type='rigid')

    return {
        'hull': hull,
        'paddles': [paddle1, paddle2]
    }

